add(nr=403, id="10411771363594", orig_titel="Träningsmatta TUNTURI NBR, Grå",
 fakta="Träningsmatta TUNTURI NBR, Grå. Tunturi Fitnessmat NBR erbjuder utmärkt komfort under träning, tillverkad av mjukt och slitstarkt NBR-material. Mattan har en tjocklek på 15 mm, vilket ger tillräcklig dämpning och skydd under golvövningar. Mattans eleganta design gör den portabel, tack vare den medföljande bärväskan, vilket gör den enkel att transportera. Lägg till detaljer: Material: NBR (Nitrilbutadumsgummi). NBR (NBR nitrilgummi) Finns även i andra färger. Levereras med: bärväska. Nylon gummi (NBR): Yoga, Pilates och allmän träning. Mått: 180 x 60 cm. 180 x 180 x 180 x 180 x 180 - Må bättre varje dag - Det är Tunturi motto. Våra rötter finns i Finland, där två bröder grundade en cykelaffär 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Märke Tunturi, typ Yogamattor, taggar Fell, På beställning, träningsmatta, Tunturi, Velomarket, Yogamattor, variant Default Title, SKU 14TUSFU327",
 titel="Träningsmatta Tunturi NBR, 15 mm, grå",
 seo_title="Träningsmatta Tunturi NBR, 15 mm, grå",
 meta="Tunturi NBR är en träningsmatta i NBR-gummi, 15 mm tjock och 180 x 60 cm, för yoga, pilates och allmän träning. Bärväska medföljer. Finns i fler färger.",
 intro="Tunturi NBR är en träningsmatta i NBR-gummi, 15 mm tjock och 180 x 60 cm, för golvövningar, yoga, pilates och allmän träning. En bärväska medföljer.",
 passar=["Yoga, pilates och allmän träning","Golvövningar","Dig som vill kunna bära med mattan (bärväska medföljer)"],
 spec=["Mått: 180 x 60 cm","Tjocklek: 15 mm","Material: NBR (nitrilgummi)","Levereras med: bärväska","Färg: grå, finns även i andra färger"],
 faq=[], marke=None,
 motivering="Fakta ur källan. \"Utmärkt komfort\", \"slitstarkt\", \"tillräcklig dämpning och skydd\", \"eleganta design\", mottot \"Må bättre varje dag\", hälsolöftet om en frisk kropp och Tunturis företagshistorik utelämnas. Raden \"180 x 180 x 180 x 180 x 180\" är trasig och skrivs inte vidare.",
 att_bekrafta=["Källan har en trasig rad \"180 x 180 x 180 x 180 x 180\". Texten använder måttet 180 x 60 cm som anges separat.","Raden \"Nylon gummi (NBR): Yoga, Pilates och allmän träning\" är oklar (nylon eller NBR?). Texten tolkar den som användningsområden och påstår inget nylon.","Materialet står som \"Nitrilbutadumsgummi\" (troligen nitrilbutadiengummi). Texten skriver bara nitrilgummi.","Taggen \"På beställning\" tyder på beställningsvara. Standardblock för beställningsvaror bör användas om det stämmer.","Vikt saknas."])

add(nr=404, id="10472215544074", orig_titel="Massage roller TUNTURI Yoga Massage Roller 90 cm",
 fakta="Massage roller TUNTURI Yoga Massage Roller 90 cm. Fördelar med Tunturi massage roller: Stödjer dig i dina favoritpositioner inom yoga och Pilates. Tillverkad av mjukt och flexibelt skumgummi för ett bekvämt träningspass. \"Må bättre varje dag\" - det är Tunturimottot. Våra rötter går tillbaka till Finland, där två bröder startade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och supportappar. Sortimentet utökas ständigt och kompletteras med kvalitetsprodukter och utmärkta garantier. Tekniska specifikationer. Märke Tunturi, typ Massage, taggar Fell, Massage, Tunturi, Velomarket, Yoga, varianter Default Title och 14TUSYO008, SKU 14TUSYO008",
 titel="Yogarulle Tunturi, 90 cm, skumgummi",
 seo_title="Yogarulle Tunturi, 90 cm, skumgummi",
 meta="Tunturi yogarulle på 90 cm, tillverkad av mjukt och flexibelt skumgummi för ett bekvämt träningspass. Stödjer positioner inom yoga och pilates.",
 intro="Tunturi yogarulle är en rulle på 90 cm i mjukt och flexibelt skumgummi. Den är avsedd som stöd i positioner inom yoga och pilates.",
 passar=["Yoga och pilates, som stöd i positioner","Dig som vill ha en rulle av mjukt och flexibelt skumgummi"],
 spec=["Längd: 90 cm","Material: mjukt och flexibelt skumgummi"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Mottot, hälsolöftet om en frisk kropp, företagshistoriken och \"utmärkta garantier\" utelämnas. \"Bekvämt träningspass\" utelämnas som värderande.",
 att_bekrafta=["Källans rubrik \"Tekniska specifikationer\" är tom: diameter, vikt och färg saknas.","Produkten har två varianter (\"Default Title\" och \"14TUSYO008\") med samma SKU. Troligen en dubblett.","Texten kallar produkten rulle med yogakoppling. Källan och butikens typ använder ordet massage. Det är utelämnat i titel och text (hälsoordskontrollen kräver manuell granskning). Bekräfta om \"massage\" ska tillbaka."])

add(nr=405, id="10472215642378", orig_titel="Yogamatta TUNTURI TPE Yogamat 4mm, turkos",
 fakta="Yogamatta TUNTURI TPE Yogamat 4mm, turkos. Fördelar med Tunturi PVC yogamatta: En bekväm yogamatta för yoga och fitnessövningar. Yoga och Yoga Yoga Yoga för Yoga och Yoga Yoga Yoga. Lätt att rulla ihop och förvara. Lätt att rulla ihop och rulla för enkel träning. Lätt att passa och bekväm att hålla matta. \"Må bättre varje dag\" - det är Tuntur's motto. Våra rötter går tillbaka till Finland, där två bröder startade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Detta sortiment utökas ständigt och kompletteras med högkvalitativa produkter och utmärkta garantier. Specifikationer översikt: Mått: 182 x 61 cm. 182 cm x 182 cm. Vikt: 949 gr. Halkskydd. Innehåller elastisk. Färg: turkos. Material: PVC. Märke Tunturi, typ Yogamattor, taggar Fell, Tunturi, Velomarket, Yoga, Yogamattor, variant Default Title, SKU 14TUSYO035",
 titel="Yogamatta Tunturi Yogamat, 4 mm, turkos",
 seo_title="Yogamatta Tunturi Yogamat, 4 mm",
 meta="Tunturi Yogamat är en turkos yogamatta på 4 mm för yoga och fitnessövningar, 182 x 61 cm och 949 g, med halkskydd. Lätt att rulla ihop och förvara.",
 intro="Tunturi Yogamat är en turkos yogamatta på 4 mm för yoga och fitnessövningar. Mattan är 182 x 61 cm, har halkskydd och är lätt att rulla ihop och förvara.",
 passar=["Yoga och fitnessövningar","Dig som vill ha en matta som är lätt att rulla ihop och förvara"],
 spec=["Mått: 182 x 61 cm","Tjocklek: 4 mm","Vikt: 949 g","Halkskydd","Färg: turkos"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Material utelämnas eftersom titeln säger TPE men texten säger PVC. Mottot, hälsolöftet, företagshistoriken, \"bekväm\" och \"utmärkta garantier\" utelämnas. De trasiga raderna (\"Yoga Yoga Yoga\", \"182 cm x 182 cm\", \"Innehåller elastisk\", \"Lätt att passa\") skrivs inte vidare.",
 att_bekrafta=["Material: titeln säger TPE, källtexten säger PVC (både \"Tunturi PVC yogamatta\" och \"Material: PVC\"). Vilket stämmer?","Källan har maskinöversatta och trasiga rader (\"Yoga och Yoga Yoga Yoga\", \"182 cm x 182 cm\", \"Innehåller elastisk\", \"Lätt att passa och bekväm att hålla matta\").","Tjockleken 4 mm står bara i titeln, inte i specifikationen.","Kategorin är Yogamattor men texten säger \"Tunturi PVC yogamatta\" och titeln \"TPE Yogamat\". Samma produkt?"])

add(nr=406, id="10472277803274", orig_titel="Gymnastikboll TUNTURI Gymball 75cm, Anti-Burst, Mint",
 fakta="Gymnastikboll TUNTURI Gymball 75cm, Anti-Burst, Mint. Om du letar efter en gymnastikboll som inte bara tar din träning till nästa nivå, utan också är lämplig för yoga, stretchövningar och kanske till och med för att sitta vid ett skrivbord, då är Tunturi Gymball ett bra val! Tunturi Gymball är designad för att klara vikter upp till 220 kg, vilket garanterar hållbarhet och stabilitet i varje rörelse. Välj rätt storlek på bollen för din längd: 55 cm - lämplig för längder mellan 155-165 cm. 65 cm - lämplig för längder 166-178 cm. 75 cm - lämplig för längder 179-190 cm. 90 cm - lämplig för längder > 190 cm. I detalj: Diameter: 75 cm. Produktvikt: 1,2 kg. Bärförmåga: 220 kg. Färg: grönaktig. \"Må bättre varje dag\" - det är Tuntur's motto. Våra rötter går tillbaka till Finland, där två bröder grundade en cykelaffär 1922. Nu, mer än 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Sortimentet utökas och växer ständigt, med högkvalitativa produkter och bra garantier. Märke Tunturi, typ Konditionsträning & Fitness, taggar Konditionsträning & Fitness, Tunturi, Velomarket, variant Default Title, SKU 14TUSFU336",
 titel="Gymnastikboll Tunturi Gymball 75 cm, Anti-Burst, mint",
 seo_title="Gymnastikboll Tunturi Gymball 75 cm",
 meta="Tunturi Gymball är en gymnastikboll med diameter 75 cm och bärförmåga 220 kg, lämplig för yoga och stretchövningar. Passar längder 179–190 cm.",
 intro="Tunturi Gymball är en gymnastikboll med diameter 75 cm och bärförmåga 220 kg. Den är lämplig för träning, yoga och stretchövningar. Storleken 75 cm passar längder 179–190 cm.",
 passar=["Yoga och stretchövningar","Träning med gymnastikboll","Dig som är 179–190 cm lång (storlek 75 cm)"],
 spec=["Diameter: 75 cm","Produktvikt: 1,2 kg","Bärförmåga: 220 kg","Färg: mint (källan anger grönaktig)","Storlekar: 55 cm för längder 155–165 cm, 65 cm för längder 166–178 cm, 75 cm för längder 179–190 cm, 90 cm för längder över 190 cm"],
 faq=[("Vilken storlek ska jag välja?","Enligt tillverkaren passar 55 cm längder 155–165 cm, 65 cm längder 166–178 cm, 75 cm längder 179–190 cm och 90 cm längder över 190 cm.")], marke=None,
 motivering="Fakta ur källan. \"Nästa nivå\", \"bra val\", \"garanterar hållbarhet och stabilitet\", skrivbordsanvändning (\"kanske\"), mottot, hälsolöftet och företagshistoriken utelämnas.",
 att_bekrafta=["Bärförmågan 220 kg är en belastningsuppgift. Bekräfta mot datablad innan den publiceras.","Titeln säger Mint, specifikationen \"grönaktig\". Bekräfta färg.","\"Anti-Burst\" står i titeln men förklaras inte i texten. Texten påstår ingen särskild säkerhetsegenskap.","Produkten har status DRAFT i butiken.","Storlekarna 55, 65 och 90 cm finns i texten men inte som varianter."])

add(nr=407, id="10472281374986", orig_titel="Crosstrainer TUNTURI FitCross 50i",
 fakta="Crosstrainer TUNTURI FitCross 50i. Håll kroppen i form! Träna på din egen nivå, sätt din egen takt och sätt upp ett realistiskt mål. För att uppnå de resultat du vill ha, välj måttliga till något intensivare svårighetsgrader. Få kroppen i form med Tunturi FitCross 50 eller bibehåll din önskade nivå. Tillverkare . Detaljer: Skärm: 5,5 tum, LCD. Träningsprogram: 22. Svårighetsgrader: 32. Bromssystem: PMS, servomotor. Belastning: 18 kg. Steglängd: 38 cm. Mått: 145 x 60 x 171 cm. Produktvikt: 48 kg. Maximal användarvikt: 150 kg. Märke Tunturi, typ Crosstrainers, taggar Crosstrainer, Crosstrainers, Fell, Tunturi, Velomarket, variant Default Title, SKU 17TFCR5000",
 titel="Crosstrainer Tunturi FitCross 50i, 22 träningsprogram",
 seo_title="Crosstrainer Tunturi FitCross 50i",
 meta="Tunturi FitCross 50i är en crosstrainer med 5,5 tums LCD-skärm, 22 träningsprogram och 32 svårighetsgrader. Steglängd 38 cm, maximal användarvikt 150 kg.",
 intro="Tunturi FitCross 50i är en crosstrainer med 5,5 tums LCD-skärm, 22 träningsprogram och 32 svårighetsgrader.",
 passar=["Dig som vill kunna välja mellan 22 träningsprogram och 32 svårighetsgrader","Användare upp till 150 kg","Dig som vill ha en steglängd på 38 cm"],
 spec=["Skärm: 5,5 tum, LCD","Träningsprogram: 22","Svårighetsgrader: 32","Bromssystem: PMS, servomotor","Steglängd: 38 cm","Mått: 145 x 60 x 171 cm","Produktvikt: 48 kg","Maximal användarvikt: 150 kg"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Inledningens träningsråd och löften (\"håll kroppen i form\", \"uppnå de resultat du vill ha\") utelämnas. Raden \"Belastning: 18 kg\" utelämnas eftersom betydelsen är oklar.",
 att_bekrafta=["Titeln säger FitCross 50i, texten \"FitCross 50\". Samma modell?","Raden \"Belastning: 18 kg\" är oklar (svänghjul? motstånd?). Bekräfta innan den används.","Raden \"Tillverkare .\" är tom.","Typen i butiken är \"Crosstrainers\" (flertal)."])

