add(nr=412, id="10612579533066", orig_titel="Löpband TUNTURI Cardio Fit T60",
 fakta="Löpband TUNTURI Cardio Fit T60. Tunturi Cardio Fit T60 löpband är en kraftfull hopfällbar träningsmaskin för hemmabruk. Tack vare den extra breda löpytan, höga maxhastigheten och enkla förvaringen kan du ta din träning till en helt ny nivå! OBS: Löpbandet levereras färdigmonterat i kartongen och kräver ingen montering. Öppna förpackningen, lyft upp handtagen, lås dem, placera skärmen i rätt vinkel och börja träna. Tillverkad av Tunturi. Mer information: Display: LED. Träningsprogram: 44. Motor: 3,5 HK. Hastighet: 0,8–18 km/h. Lutningsnivåer: 15 (elektroniskt justerbara). Löyta: 140 × 50 cm. Mått: 170,1 × 83,5 × 134,9 cm. Hopfällda mått: 30 × 80,2 × 170,1 cm. Produktvikt: 80 kg. Maximal belastning: 130 kg. Märke Tunturi, typ Konditionsträning & Fitness, taggar Konditionsträning & Fitness, Löpband, Tunturi, Velomarket, variant Default Title, SKU 24TCFT6000",
 titel="Löpband Tunturi Cardio Fit T60, hopfällbart",
 seo_title="Löpband Tunturi Cardio Fit T60",
 meta="Tunturi Cardio Fit T60 är ett hopfällbart löpband för hemmabruk med motor på 3,5 hk, hastighet 0,8–18 km/h, 15 lutningsnivåer och 44 träningsprogram.",
 intro="Tunturi Cardio Fit T60 är ett hopfällbart löpband för hemmabruk. Det levereras färdigmonterat i kartongen och kräver ingen montering.",
 passar=["Dig som vill ha ett löpband för hemmabruk som går att fälla ihop","Dig som vill ha ett löpband som levereras färdigmonterat","Användare upp till 130 kg"],
 spec=["Display: LED","Träningsprogram: 44","Motor: 3,5 hk","Hastighet: 0,8–18 km/h","Lutningsnivåer: 15, elektroniskt justerbara","Löpyta: 140 × 50 cm","Mått: 170,1 × 83,5 × 134,9 cm","Hopfällda mått: 30 × 80,2 × 170,1 cm","Produktvikt: 80 kg","Maximal belastning: 130 kg"],
 faq=[("Behöver löpbandet monteras?","Nej, enligt tillverkaren levereras det färdigmonterat och kräver ingen montering. Öppna förpackningen, lyft upp handtagen, lås dem, placera skärmen i rätt vinkel.")], marke=None,
 motivering="Fakta ur källan. \"Kraftfull\", \"extra breda löpytan\", \"höga maxhastigheten\", \"enkla förvaringen\" och \"en helt ny nivå\" utelämnas som värderande eller löften. \"Löyta\" rättas till löpyta.",
 att_bekrafta=["Hopfällda måtten (30 × 80,2 × 170,1 cm) anger 170,1 cm som en dimension, samma som längden uppfälld. Troligen rimligt (höjd vs längd), men bekräfta.","Källan skriver \"Löyta\" (troligen löpyta).","Produkten har status DRAFT i butiken.","Maximal belastning 130 kg är en användarvikt/belastningsuppgift. Bekräfta mot datablad."])

add(nr=413, id="10472218984714", orig_titel="Pulsband TUNTURI Digital HR Armband",
 fakta="Pulsband TUNTURI Digital HR Armband. Tunturi's digitala pulsmätare ser till att du alltid tränar med rätt intensitet – varken för lätt eller bortom dina förmågor. Denna sensor övervakar intensiteten i ditt träningspass i realtid. En integrerad LED-lampa indikerar tydligt vilken pulszon du befinner dig i. Pulsmätarens handledsband har fördelen att du slipper bära ett bälte som sitter åt runt bröstet – trä bara ett bekvämt band över över- eller underarmen. Bandet är tillverkat av ventilerande, mjuk och bekväm nylon, och kan enkelt justeras med hjälp av en dragsko. Dessutom fungerar denna digitala pulsmätare även som en kadenssensor, vilket gör att du kan övervaka antalet steg per minut när du går eller springer. Fördelar ✓ Kan bäras på antingen över- eller underarmen. ✓ Fungerar även som kadenssensor ✓ Kompatibel med populära träningsappar ✓ LED-lampa indikerar aktuell pulszon med färg. ✓ Lämplig för alla typer av träningspass – både inomhus- och utomhusbruk. Bluetooth, ANT+ och vattentät. Pulsmätarens armband är kompatibelt med populära träningsappar som Tunturi Routes, Tunturi Training, Kinomap, Zwift och Strava. Sensorn fungerar med alla träningsenheter, GPS-sportklockor och cykeldatorer som stöder Bluetooth- eller ANT+-anslutning. Pulsmätaren är även lämplig för simmare: den är vattentät upp till trettio minuter på ett maximalt djup av en meter. \"Må bättre varje dag\" är Tunturis motto. Våra rötter går tillbaka till 1922, då två bröder grundade en cykelaffär i Finland. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöttar dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Vårt produktsortiment utökas och förbättras ständigt, och vi erbjuder kvalitetsprodukter och utmärkta garantier. Märke Tunturi, typ Crosstrainers, taggar Crosstrainers, Fell, puls, pulsklocka, pulsmätare, Tunturi, Velomarket, variant Default Title, SKU 14TUSRU186",
 titel="Pulsmätare Tunturi Digital HR Armband, Bluetooth och ANT+",
 seo_title="Pulsmätare Tunturi Digital HR Armband",
 meta="Tunturi Digital HR Armband är en digital pulsmätare för över- eller underarmen med LED-lampa för pulszon, kadenssensor, Bluetooth och ANT+.",
 intro="Tunturi Digital HR Armband är en digital pulsmätare som bärs på över- eller underarmen i ett justerbart nylonband. En LED-lampa visar med färg vilken pulszon du befinner dig i.",
 passar=["Dig som vill mäta puls utan bröstbälte","Dig som vill ansluta till träningsappar som Tunturi Routes, Tunturi Training, Kinomap, Zwift och Strava","Träning både inomhus och utomhus"],
 spec=["Bärs på över- eller underarmen","Band: nylon, justerbart med dragsko","LED-lampa som visar aktuell pulszon med färg","Fungerar även som kadenssensor (steg per minut vid gång eller löpning)","Anslutning: Bluetooth och ANT+","Kompatibel med Tunturi Routes, Tunturi Training, Kinomap, Zwift och Strava","Vattentät upp till trettio minuter på ett maximalt djup av en meter"],
 faq=[("Kan pulsmätaren användas vid simning?","Enligt tillverkaren är den vattentät upp till trettio minuter på ett maximalt djup av en meter."),("Vilka appar fungerar den med?","Tunturi Routes, Tunturi Training, Kinomap, Zwift och Strava.")], marke=None,
 motivering="Fakta ur källan. \"Rätt intensitet – varken för lätt eller bortom dina förmågor\", \"tydligt\", \"bekväm\", \"fördelen\", mottot, hälsolöftet, företagshistoriken och \"utmärkta garantier\" utelämnas. Sensorns märkning \"Pulsband\" i titeln ändras till pulsmätare enligt källans eget ord.",
 att_bekrafta=["Produkttypen i butiken är \"Crosstrainers\", vilket inte stämmer. Bör rättas.","Batterityp, batteritid och vikt saknas. Om produkten har batteri bör den hanteras som säkerhetsprodukt.","Källan säger \"alla träningsenheter\" kompatibla med Bluetooth/ANT+. Texten nämner bara de uppräknade apparna.","Titeln \"Pulsband\" och källans \"pulsmätare\"/\"armband\" används om vartannat."])

add(nr=414, id="10472271184138", orig_titel="Boxningshandskar Tunturi Allround Boxing Gloves 14oz",
 fakta="Boxningshandskar Tunturi Allround Boxing Gloves 14oz. Tunturi Allround Boxing Gloves är universella boxningshandskar. Tack vare sitt syntetiska läder och mjuka stoppning är de mycket mindre känsliga för stötar och skyddar både dig och din motståndare från skador. Dessutom, tack vare den breda kardborren, har även handleden bra stöd, lämplig för alla typer av boxning. Mer information: Storlek: L 30,5 x B 16 x H 12,5 cm. Vikt: 290g. Material: konstläder. Volym: 14 oz. Märke Tunturi, typ Boxningsutrustning, taggar Boxning, Boxningsutrustning, Fell, Tunturi, Velomarket, variant Default Title, SKU 14TUSBO013",
 titel="Boxningshandskar Tunturi Allround, 14 oz, konstläder",
 seo_title="Boxningshandskar Tunturi Allround 14 oz",
 meta="Tunturi Allround Boxing Gloves är universella boxningshandskar i konstläder med mjuk stoppning och bred kardborre. Volym 14 oz, vikt 290 g.",
 intro="Tunturi Allround Boxing Gloves är universella boxningshandskar i konstläder med mjuk stoppning och bred kardborre. De är avsedda för alla typer av boxning.",
 passar=["Boxning av alla slag","Dig som vill ha handskar med bred kardborre kring handleden","Dig som söker 14 oz"],
 spec=["Volym: 14 oz","Storlek: L 30,5 x B 16 x H 12,5 cm","Vikt: 290 g","Material: konstläder","Mjuk stoppning","Bred kardborre"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Skyddspåståendena (\"mycket mindre känsliga för stötar\", \"skyddar både dig och din motståndare från skador\", \"bra stöd\" för handleden) utelämnas som skyddsloften utan källa i form av test eller standard.",
 att_bekrafta=["Skyddsloftet i källan (skydd mot skador) är inte belagt med test eller standard och är inte med. Bekräfta om det ska användas.","Källan saknar uppgift om par/styck och om handsken passar viss handstorlek eller vikt.","\"Volym: 14 oz\" är troligen vikt/storlek enligt boxningsstandard, men källan förklarar det inte.","Syntetiskt läder och konstläder används om vartannat i källan. Texten skriver konstläder."])
